export const DOCS_HTML_CONTENT = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  \n  <!-- Primary Meta Tags -->\n  <title>Pontis — Universal AI Gateway & CLI Runtime Bridge</title>\n  <meta name=\"title\" content=\"Pontis — Universal AI Gateway & CLI Runtime Bridge\">\n  <meta name=\"description\" content=\"Bridge any terminal AI coding agent (Claude Code, OpenAI Codex CLI, Hermes Agent, OpenCode, Pi) to any LLM backend (Google AI Studio, OpenCode, Cloudflare Workers AI, Local Ollama) with real-time bidirectional protocol translation.\">\n  <meta name=\"keywords\" content=\"Claude Code, Codex CLI, Hermes Agent, OpenCode, Pi agent, AI Gateway, LLM Proxy, Ollama, Gemini 2.5, Cloudflare AI Gateway, Protocol Translation\">\n  <meta name=\"author\" content=\"Khrees\">\n  <meta name=\"theme-color\" content=\"#07090e\">\n\n  <!-- Open Graph / Facebook -->\n  <meta property=\"og:type\" content=\"website\">\n  <meta property=\"og:url\" content=\"https://pontis.khrees.com/\">\n  <meta property=\"og:title\" content=\"Pontis — Universal AI Gateway & CLI Runtime Bridge\">\n  <meta property=\"og:description\" content=\"Run Claude Code, Codex, Hermes, OpenCode, and Pi with free Google AI Studio, OpenCode cloud, Cloudflare Workers AI, or local Ollama with zero friction.\">\n  \n  <!-- Twitter -->\n  <meta property=\"twitter:card\" content=\"summary_large_image\">\n  <meta property=\"twitter:title\" content=\"Pontis — Universal AI Gateway & CLI Runtime Bridge\">\n  <meta property=\"twitter:description\" content=\"Run Claude Code, Codex, Hermes, OpenCode, and Pi with free Google AI Studio, OpenCode cloud, Cloudflare Workers AI, or local Ollama with zero friction.\">\n\n  <!-- Typography: Inter & JetBrains Mono -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=JetBrains+Mono:ital,wght@0,400;0,500;0,600;0,700;1,400&display=swap\" rel=\"stylesheet\">\n\n  <style>\n    /* ─────────────────────────────────────────────────────────────\n       1. Design Tokens & Apple-Inspired Material Foundations\n       ───────────────────────────────────────────────────────────── */\n    :root {\n      --bg-canvas: #07090e;\n      --bg-surface: #0e111a;\n      --bg-surface-raised: #141824;\n      --bg-surface-glass: rgba(14, 17, 26, 0.72);\n      --bg-surface-active: rgba(255, 255, 255, 0.06);\n      \n      --border-subtle: rgba(255, 255, 255, 0.08);\n      --border-medium: rgba(255, 255, 255, 0.14);\n      --border-highlight: rgba(167, 139, 250, 0.4);\n      --border-focus: #a78bfa;\n\n      --text-primary: #f8fafc;\n      --text-secondary: #94a3b8;\n      --text-muted: #64748b;\n      --text-faint: #475569;\n\n      --brand-primary: #a78bfa;     /* Lilac / Violet */\n      --brand-cyan: #38bdf8;        /* Vivid Cyan */\n      --brand-emerald: #34d399;     /* Emerald Success */\n      --brand-amber: #fbbf24;      /* Warm Amber */\n      --brand-rose: #f87171;       /* Rose Error */\n\n      --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Segoe UI', Roboto, sans-serif;\n      --font-mono: 'JetBrains Mono', 'SF Mono', Menlo, Monaco, Consolas, monospace;\n\n      --radius-sm: 8px;\n      --radius-md: 12px;\n      --radius-lg: 18px;\n      --radius-xl: 24px;\n      --radius-pill: 9999px;\n\n      --shadow-ambient: 0 4px 24px -1px rgba(0, 0, 0, 0.4);\n      --shadow-elevation: 0 16px 40px -8px rgba(0, 0, 0, 0.6);\n      --shadow-glow: 0 0 40px -10px rgba(167, 139, 250, 0.25);\n\n      --ease-spring: cubic-bezier(0.16, 1, 0.3, 1);\n      --ease-instant: cubic-bezier(0.05, 0.7, 0.1, 1);\n      --duration-fast: 150ms;\n      --duration-base: 250ms;\n      --duration-slow: 400ms;\n    }\n\n    /* ─────────────────────────────────────────────────────────────\n       2. Base Reset & Typography\n       ───────────────────────────────────────────────────────────── */\n    *, *::before, *::after {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n      -webkit-font-smoothing: antialiased;\n      -moz-osx-font-smoothing: grayscale;\n    }\n\n    html {\n      scroll-behavior: smooth;\n      font-size: 16px;\n      background-color: var(--bg-canvas);\n      color: var(--text-primary);\n    }\n\n    body {\n      font-family: var(--font-sans);\n      line-height: 1.6;\n      background-color: var(--bg-canvas);\n      background-image: \n        radial-gradient(ellipse 80% 50% at 50% -15%, rgba(167, 139, 250, 0.12), transparent 70%),\n        radial-gradient(circle 600px at 90% 20%, rgba(56, 189, 248, 0.05), transparent 80%);\n      background-attachment: fixed;\n      min-height: 100vh;\n      overflow-x: hidden;\n    }\n\n    ::selection {\n      background: rgba(167, 139, 250, 0.3);\n      color: #fff;\n    }\n\n    a {\n      color: var(--brand-primary);\n      text-decoration: none;\n      transition: color var(--duration-fast) ease, opacity var(--duration-fast) ease;\n    }\n\n    a:hover {\n      color: var(--brand-cyan);\n    }\n\n    button {\n      font-family: inherit;\n      border: none;\n      background: none;\n      cursor: pointer;\n    }\n\n    code, pre {\n      font-family: var(--font-mono);\n      font-feature-settings: \"liga\" 0;\n    }\n\n    .container {\n      width: 100%;\n      max-width: 1200px;\n      margin: 0 auto;\n      padding: 0 24px;\n    }\n\n    /* ─────────────────────────────────────────────────────────────\n       3. Translucent Header & Navigation\n       ───────────────────────────────────────────────────────────── */\n    header.site-header {\n      position: sticky;\n      top: 0;\n      z-index: 100;\n      backdrop-filter: blur(20px) saturate(180%);\n      -webkit-backdrop-filter: blur(20px) saturate(180%);\n      background: var(--bg-surface-glass);\n      border-bottom: 1px solid var(--border-subtle);\n      transition: border-color var(--duration-base) ease;\n    }\n\n    .header-inner {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      height: 68px;\n    }\n\n    .brand-link {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      color: var(--text-primary);\n      font-weight: 700;\n      font-size: 1.15rem;\n      letter-spacing: -0.02em;\n    }\n\n    .brand-symbol {\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      width: 32px;\n      height: 32px;\n      border-radius: var(--radius-sm);\n      background: linear-gradient(135deg, rgba(167, 139, 250, 0.25), rgba(56, 189, 248, 0.2));\n      border: 1px solid rgba(167, 139, 250, 0.35);\n      color: var(--brand-primary);\n      font-size: 0.95rem;\n    }\n\n    .brand-version {\n      font-size: 0.72rem;\n      font-family: var(--font-mono);\n      font-weight: 600;\n      padding: 2px 8px;\n      background: rgba(255, 255, 255, 0.06);\n      border: 1px solid var(--border-subtle);\n      border-radius: var(--radius-pill);\n      color: var(--text-secondary);\n    }\n\n    nav.nav-menu {\n      display: flex;\n      align-items: center;\n      gap: 28px;\n    }\n\n    .nav-item {\n      font-size: 0.9rem;\n      font-weight: 500;\n      color: var(--text-secondary);\n      transition: color var(--duration-fast) ease;\n    }\n\n    .nav-item:hover {\n      color: var(--text-primary);\n    }\n\n    .header-actions {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n    }\n\n    .btn {\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      gap: 8px;\n      font-size: 0.88rem;\n      font-weight: 600;\n      padding: 8px 16px;\n      border-radius: var(--radius-sm);\n      transition: transform var(--duration-fast) var(--ease-instant), \n                  background-color var(--duration-fast) ease, \n                  border-color var(--duration-fast) ease,\n                  box-shadow var(--duration-fast) ease;\n    }\n\n    .btn:active {\n      transform: scale(0.97);\n    }\n\n    .btn-primary {\n      background: var(--text-primary);\n      color: #000;\n      border: 1px solid transparent;\n    }\n\n    .btn-primary:hover {\n      background: #ffffff;\n      color: #000;\n      box-shadow: 0 0 20px rgba(255, 255, 255, 0.2);\n    }\n\n    .btn-secondary {\n      background: rgba(255, 255, 255, 0.05);\n      color: var(--text-primary);\n      border: 1px solid var(--border-subtle);\n    }\n\n    .btn-secondary:hover {\n      background: rgba(255, 255, 255, 0.09);\n      border-color: var(--border-medium);\n    }\n\n    /* ─────────────────────────────────────────────────────────────\n       4. Hero Section & Interactive Terminal Demonstration\n       ───────────────────────────────────────────────────────────── */\n    .hero-section {\n      padding: 72px 0 60px;\n      position: relative;\n    }\n\n    .hero-grid {\n      display: grid;\n      grid-template-columns: 1.15fr 0.95fr;\n      gap: 48px;\n      align-items: center;\n    }\n\n    .hero-tag {\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      font-size: 0.8rem;\n      font-weight: 600;\n      color: var(--brand-primary);\n      background: rgba(167, 139, 250, 0.08);\n      border: 1px solid rgba(167, 139, 250, 0.2);\n      padding: 4px 12px;\n      border-radius: var(--radius-pill);\n      margin-bottom: 20px;\n      letter-spacing: 0.02em;\n    }\n\n    .hero-tag-dot {\n      width: 6px;\n      height: 6px;\n      border-radius: 50%;\n      background: var(--brand-emerald);\n      box-shadow: 0 0 8px var(--brand-emerald);\n    }\n\n    h1.hero-title {\n      font-size: clamp(2.4rem, 4.2vw, 3.8rem);\n      font-weight: 800;\n      line-height: 1.08;\n      letter-spacing: -0.035em;\n      color: var(--text-primary);\n      margin-bottom: 20px;\n    }\n\n    .hero-title span.gradient {\n      background: linear-gradient(135deg, #f8fafc 20%, #a78bfa 70%, #38bdf8 100%);\n      -webkit-background-clip: text;\n      -webkit-text-fill-color: transparent;\n    }\n\n    p.hero-subtitle {\n      font-size: 1.12rem;\n      line-height: 1.65;\n      color: var(--text-secondary);\n      margin-bottom: 32px;\n      max-width: 540px;\n    }\n\n    .hero-cta-group {\n      display: flex;\n      flex-wrap: wrap;\n      align-items: center;\n      gap: 14px;\n      margin-bottom: 36px;\n    }\n\n    .copy-install-box {\n      display: inline-flex;\n      align-items: center;\n      background: rgba(0, 0, 0, 0.45);\n      border: 1px solid var(--border-medium);\n      border-radius: var(--radius-sm);\n      padding: 4px 6px 4px 14px;\n      font-family: var(--font-mono);\n      font-size: 0.85rem;\n      color: var(--text-secondary);\n      gap: 12px;\n    }\n\n    .copy-install-box code {\n      color: var(--brand-cyan);\n    }\n\n    .copy-btn {\n      padding: 6px 12px;\n      background: rgba(255, 255, 255, 0.07);\n      border: 1px solid var(--border-subtle);\n      border-radius: 6px;\n      color: var(--text-primary);\n      font-size: 0.78rem;\n      font-weight: 600;\n      transition: all var(--duration-fast) ease;\n    }\n\n    .copy-btn:hover {\n      background: rgba(255, 255, 255, 0.14);\n      color: #fff;\n    }\n\n    .hero-badges {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 20px;\n      font-size: 0.85rem;\n      color: var(--text-muted);\n    }\n\n    .hero-badge-item {\n      display: flex;\n      align-items: center;\n      gap: 6px;\n    }\n\n    .hero-badge-item span.icon {\n      color: var(--brand-emerald);\n      font-weight: bold;\n    }\n\n    /* Terminal Simulator Card */\n    .terminal-card {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-medium);\n      border-radius: var(--radius-lg);\n      box-shadow: var(--shadow-elevation), var(--shadow-glow);\n      overflow: hidden;\n      display: flex;\n      flex-direction: column;\n    }\n\n    .terminal-header {\n      background: rgba(255, 255, 255, 0.03);\n      border-bottom: 1px solid var(--border-subtle);\n      padding: 12px 16px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n    }\n\n    .window-controls {\n      display: flex;\n      gap: 7px;\n    }\n\n    .window-dot {\n      width: 11px;\n      height: 11px;\n      border-radius: 50%;\n      background: rgba(255, 255, 255, 0.12);\n    }\n\n    .window-dot.red { background: #ff5f56; }\n    .window-dot.yellow { background: #ffbd2e; }\n    .window-dot.green { background: #27c93f; }\n\n    .terminal-tabs {\n      display: flex;\n      gap: 4px;\n      background: rgba(0, 0, 0, 0.3);\n      padding: 3px;\n      border-radius: var(--radius-sm);\n      border: 1px solid var(--border-subtle);\n    }\n\n    .t-tab {\n      padding: 4px 10px;\n      font-size: 0.75rem;\n      font-weight: 600;\n      color: var(--text-muted);\n      border-radius: 5px;\n      transition: all var(--duration-fast) ease;\n    }\n\n    .t-tab.active {\n      background: var(--bg-surface-raised);\n      color: var(--text-primary);\n      box-shadow: 0 2px 6px rgba(0, 0, 0, 0.4);\n    }\n\n    .terminal-body {\n      padding: 20px;\n      font-family: var(--font-mono);\n      font-size: 0.84rem;\n      line-height: 1.7;\n      min-height: 280px;\n      color: var(--text-secondary);\n      background: #090b10;\n    }\n\n    .t-line {\n      display: flex;\n      gap: 10px;\n      margin-bottom: 6px;\n    }\n\n    .t-prompt {\n      color: var(--brand-primary);\n      user-select: none;\n      font-weight: 600;\n    }\n\n    .t-cmd {\n      color: #fff;\n      font-weight: 500;\n    }\n\n    .t-dim { color: var(--text-muted); }\n    .t-cyan { color: var(--brand-cyan); }\n    .t-green { color: var(--brand-emerald); }\n    .t-amber { color: var(--brand-amber); }\n    .t-purple { color: var(--brand-primary); }\n\n    /* ─────────────────────────────────────────────────────────────\n       5. Architecture & Live Protocol Bridge Visualizer\n       ───────────────────────────────────────────────────────────── */\n    .section {\n      padding: 80px 0;\n      border-top: 1px solid var(--border-subtle);\n      position: relative;\n    }\n\n    .section-header {\n      text-align: center;\n      max-width: 680px;\n      margin: 0 auto 54px;\n    }\n\n    .section-tag {\n      display: inline-block;\n      font-size: 0.78rem;\n      font-weight: 700;\n      text-transform: uppercase;\n      letter-spacing: 0.1em;\n      color: var(--brand-primary);\n      margin-bottom: 12px;\n    }\n\n    h2.section-title {\n      font-size: clamp(1.8rem, 3vw, 2.6rem);\n      font-weight: 800;\n      letter-spacing: -0.03em;\n      color: var(--text-primary);\n      margin-bottom: 16px;\n    }\n\n    p.section-desc {\n      font-size: 1.05rem;\n      color: var(--text-secondary);\n      line-height: 1.6;\n    }\n\n    /* Architecture Visualizer Diagram */\n    .bridge-diagram {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-medium);\n      border-radius: var(--radius-xl);\n      padding: 40px;\n      box-shadow: var(--shadow-ambient);\n      display: grid;\n      grid-template-columns: 1fr 60px 1.25fr 60px 1fr;\n      align-items: center;\n      gap: 16px;\n      margin-bottom: 32px;\n    }\n\n    .diagram-col {\n      display: flex;\n      flex-direction: column;\n      gap: 12px;\n    }\n\n    .col-title {\n      font-size: 0.78rem;\n      font-weight: 700;\n      text-transform: uppercase;\n      letter-spacing: 0.08em;\n      color: var(--text-muted);\n      margin-bottom: 4px;\n      display: flex;\n      align-items: center;\n      gap: 6px;\n    }\n\n    .diagram-card {\n      background: var(--bg-surface-raised);\n      border: 1px solid var(--border-subtle);\n      border-radius: var(--radius-md);\n      padding: 12px 16px;\n      font-size: 0.86rem;\n      font-weight: 600;\n      color: var(--text-primary);\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      transition: all var(--duration-fast) ease;\n    }\n\n    .diagram-card:hover {\n      border-color: var(--border-highlight);\n      background: rgba(255, 255, 255, 0.05);\n      transform: translateY(-2px);\n    }\n\n    .diagram-card span.badge-protocol {\n      font-size: 0.7rem;\n      font-family: var(--font-mono);\n      padding: 2px 6px;\n      border-radius: 4px;\n      background: rgba(255, 255, 255, 0.06);\n      color: var(--text-secondary);\n    }\n\n    .hub-box {\n      background: linear-gradient(180deg, rgba(167, 139, 250, 0.12) 0%, rgba(56, 189, 248, 0.08) 100%);\n      border: 1px solid var(--border-highlight);\n      border-radius: var(--radius-lg);\n      padding: 24px 20px;\n      text-align: center;\n      box-shadow: 0 8px 30px rgba(167, 139, 250, 0.15);\n    }\n\n    .hub-title {\n      font-size: 1.05rem;\n      font-weight: 800;\n      color: #fff;\n      margin-bottom: 8px;\n    }\n\n    .hub-desc {\n      font-size: 0.8rem;\n      color: var(--text-secondary);\n      line-height: 1.5;\n      margin-bottom: 16px;\n    }\n\n    .hub-features {\n      display: flex;\n      flex-direction: column;\n      gap: 6px;\n      text-align: left;\n      font-size: 0.78rem;\n      font-family: var(--font-mono);\n      color: var(--text-muted);\n    }\n\n    .hub-feature-item {\n      display: flex;\n      align-items: center;\n      gap: 6px;\n      background: rgba(0, 0, 0, 0.25);\n      padding: 4px 8px;\n      border-radius: 4px;\n    }\n\n    .hub-feature-item span.chk { color: var(--brand-emerald); }\n\n    .connector-arrow {\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      color: var(--text-faint);\n      font-size: 1.2rem;\n    }\n\n    /* ─────────────────────────────────────────────────────────────\n       6. Interactive Sandbox & Launch Command Generator\n       ───────────────────────────────────────────────────────────── */\n    .sandbox-panel {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-medium);\n      border-radius: var(--radius-xl);\n      overflow: hidden;\n      display: grid;\n      grid-template-columns: 340px 1fr;\n      box-shadow: var(--shadow-elevation);\n    }\n\n    .sandbox-sidebar {\n      background: rgba(0, 0, 0, 0.35);\n      border-right: 1px solid var(--border-subtle);\n      padding: 28px;\n      display: flex;\n      flex-direction: column;\n      gap: 24px;\n    }\n\n    .control-group {\n      display: flex;\n      flex-direction: column;\n      gap: 8px;\n    }\n\n    .control-label {\n      font-size: 0.8rem;\n      font-weight: 700;\n      text-transform: uppercase;\n      letter-spacing: 0.05em;\n      color: var(--text-secondary);\n    }\n\n    .select-pill-group {\n      display: grid;\n      grid-template-columns: repeat(2, 1fr);\n      gap: 6px;\n    }\n\n    .pill-btn {\n      padding: 8px 10px;\n      font-size: 0.82rem;\n      font-weight: 600;\n      color: var(--text-secondary);\n      background: rgba(255, 255, 255, 0.04);\n      border: 1px solid var(--border-subtle);\n      border-radius: var(--radius-sm);\n      text-align: center;\n      transition: all var(--duration-fast) ease;\n    }\n\n    .pill-btn:hover {\n      background: rgba(255, 255, 255, 0.08);\n      color: var(--text-primary);\n    }\n\n    .pill-btn.active {\n      background: var(--brand-primary);\n      color: #000;\n      border-color: var(--brand-primary);\n      font-weight: 700;\n    }\n\n    .custom-select {\n      width: 100%;\n      padding: 10px 12px;\n      background: var(--bg-surface-raised);\n      border: 1px solid var(--border-subtle);\n      border-radius: var(--radius-sm);\n      color: var(--text-primary);\n      font-family: var(--font-sans);\n      font-size: 0.88rem;\n      font-weight: 500;\n      outline: none;\n      cursor: pointer;\n    }\n\n    .custom-select:focus {\n      border-color: var(--brand-primary);\n    }\n\n    .sandbox-content {\n      padding: 28px;\n      display: flex;\n      flex-direction: column;\n      gap: 20px;\n      background: var(--bg-surface);\n    }\n\n    .sandbox-code-block {\n      background: #090b10;\n      border: 1px solid var(--border-subtle);\n      border-radius: var(--radius-md);\n      padding: 18px 20px;\n      position: relative;\n    }\n\n    .code-title {\n      font-size: 0.75rem;\n      font-family: var(--font-mono);\n      font-weight: 700;\n      text-transform: uppercase;\n      letter-spacing: 0.08em;\n      color: var(--text-muted);\n      margin-bottom: 8px;\n    }\n\n    .code-body {\n      font-family: var(--font-mono);\n      font-size: 0.9rem;\n      color: var(--brand-cyan);\n      white-space: pre-wrap;\n      word-break: break-all;\n    }\n\n    /* ─────────────────────────────────────────────────────────────\n       7. Supported Providers & Matrix\n       ───────────────────────────────────────────────────────────── */\n    .grid-4 {\n      display: grid;\n      grid-template-columns: repeat(4, 1fr);\n      gap: 20px;\n    }\n\n    .provider-card {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-subtle);\n      border-radius: var(--radius-lg);\n      padding: 28px 24px;\n      display: flex;\n      flex-direction: column;\n      gap: 16px;\n      transition: all var(--duration-base) var(--ease-spring);\n    }\n\n    .provider-card:hover {\n      border-color: var(--border-medium);\n      transform: translateY(-4px);\n      box-shadow: var(--shadow-ambient);\n    }\n\n    .card-icon-header {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n    }\n\n    .provider-badge {\n      font-size: 0.72rem;\n      font-weight: 700;\n      padding: 3px 8px;\n      border-radius: var(--radius-pill);\n      text-transform: uppercase;\n      letter-spacing: 0.04em;\n    }\n\n    .badge-free {\n      background: rgba(52, 211, 153, 0.12);\n      color: var(--brand-emerald);\n      border: 1px solid rgba(52, 211, 153, 0.25);\n    }\n\n    .badge-local {\n      background: rgba(56, 189, 248, 0.12);\n      color: var(--brand-cyan);\n      border: 1px solid rgba(56, 189, 248, 0.25);\n    }\n\n    .badge-cloud {\n      background: rgba(251, 191, 36, 0.12);\n      color: var(--brand-amber);\n      border: 1px solid rgba(251, 191, 36, 0.25);\n    }\n\n    h3.card-title {\n      font-size: 1.2rem;\n      font-weight: 700;\n      color: var(--text-primary);\n    }\n\n    p.card-desc {\n      font-size: 0.88rem;\n      color: var(--text-secondary);\n      line-height: 1.55;\n    }\n\n    .model-pill-list {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 6px;\n      margin-top: auto;\n      padding-top: 12px;\n      border-top: 1px solid var(--border-subtle);\n    }\n\n    .model-tag {\n      font-size: 0.74rem;\n      font-family: var(--font-mono);\n      background: rgba(255, 255, 255, 0.05);\n      padding: 2px 7px;\n      border-radius: 4px;\n      color: var(--text-secondary);\n    }\n\n    /* ─────────────────────────────────────────────────────────────\n       8. CLI Commands & Endpoints Reference\n       ───────────────────────────────────────────────────────────── */\n    .reference-table-wrap {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-subtle);\n      border-radius: var(--radius-lg);\n      overflow: hidden;\n    }\n\n    table.ref-table {\n      width: 100%;\n      border-collapse: collapse;\n      text-align: left;\n      font-size: 0.9rem;\n    }\n\n    table.ref-table th {\n      background: rgba(255, 255, 255, 0.02);\n      border-bottom: 1px solid var(--border-medium);\n      padding: 14px 20px;\n      font-weight: 700;\n      font-size: 0.78rem;\n      text-transform: uppercase;\n      letter-spacing: 0.06em;\n      color: var(--text-muted);\n    }\n\n    table.ref-table td {\n      padding: 16px 20px;\n      border-bottom: 1px solid var(--border-subtle);\n      color: var(--text-secondary);\n    }\n\n    table.ref-table tr:last-child td {\n      border-bottom: none;\n    }\n\n    table.ref-table code {\n      color: var(--brand-primary);\n      font-size: 0.84rem;\n      background: rgba(167, 139, 250, 0.08);\n      padding: 2px 6px;\n      border-radius: 4px;\n    }\n\n    /* ─────────────────────────────────────────────────────────────\n       9. FAQ & Accordion\n       ───────────────────────────────────────────────────────────── */\n    .faq-list {\n      display: flex;\n      flex-direction: column;\n      gap: 14px;\n      max-width: 840px;\n      margin: 0 auto;\n    }\n\n    .faq-item {\n      background: var(--bg-surface);\n      border: 1px solid var(--border-subtle);\n      border-radius: var(--radius-md);\n      overflow: hidden;\n      transition: border-color var(--duration-fast) ease;\n    }\n\n    .faq-item:hover {\n      border-color: var(--border-medium);\n    }\n\n    .faq-trigger {\n      width: 100%;\n      padding: 20px 24px;\n      text-align: left;\n      font-size: 1.05rem;\n      font-weight: 600;\n      color: var(--text-primary);\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 16px;\n    }\n\n    .faq-icon {\n      font-size: 1.2rem;\n      color: var(--text-muted);\n      transition: transform var(--duration-fast) ease;\n    }\n\n    .faq-content {\n      padding: 0 24px 22px;\n      color: var(--text-secondary);\n      font-size: 0.94rem;\n      line-height: 1.65;\n      display: none;\n    }\n\n    .faq-item.open .faq-content {\n      display: block;\n    }\n\n    .faq-item.open .faq-icon {\n      transform: rotate(45deg);\n      color: var(--brand-primary);\n    }\n\n    /* ─────────────────────────────────────────────────────────────\n       10. Footer\n       ───────────────────────────────────────────────────────────── */\n    footer.site-footer {\n      border-top: 1px solid var(--border-subtle);\n      padding: 48px 0;\n      background: #05060a;\n      color: var(--text-muted);\n      font-size: 0.86rem;\n    }\n\n    .footer-inner {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      flex-wrap: wrap;\n      gap: 20px;\n    }\n\n    /* ─────────────────────────────────────────────────────────────\n       11. Responsive Breakpoints\n       ───────────────────────────────────────────────────────────── */\n    @media (max-width: 992px) {\n      .hero-grid {\n        grid-template-columns: 1fr;\n      }\n      .bridge-diagram {\n        grid-template-columns: 1fr;\n        gap: 24px;\n      }\n      .connector-arrow {\n        transform: rotate(90deg);\n      }\n      .sandbox-panel {\n        grid-template-columns: 1fr;\n      }\n      .grid-4 {\n        grid-template-columns: repeat(2, 1fr);\n      }\n    }\n\n    @media (max-width: 640px) {\n      .grid-4 {\n        grid-template-columns: 1fr;\n      }\n      nav.nav-menu {\n        display: none;\n      }\n    }\n  </style>\n</head>\n<body>\n\n  <!-- Translucent Navigation Header -->\n  <header class=\"site-header\">\n    <div class=\"container\">\n      <div class=\"header-inner\">\n        <a href=\"#\" class=\"brand-link\">\n          <span class=\"brand-symbol\">◆</span>\n          <span>Pontis</span>\n          <span class=\"brand-version\">v1.1.0</span>\n        </a>\n\n        <nav class=\"nav-menu\">\n          <a href=\"#architecture\" class=\"nav-item\">Architecture</a>\n          <a href=\"#sandbox\" class=\"nav-item\">Sandbox</a>\n          <a href=\"#providers\" class=\"nav-item\">Providers</a>\n          <a href=\"#clients\" class=\"nav-item\">Coding Agents</a>\n          <a href=\"#cli\" class=\"nav-item\">CLI Manual</a>\n          <a href=\"#faq\" class=\"nav-item\">FAQ</a>\n        </nav>\n\n        <div class=\"header-actions\">\n          <a href=\"https://github.com/khrees/pontis\" target=\"_blank\" rel=\"noreferrer\" class=\"btn btn-secondary\">\n            <span>GitHub</span>\n          </a>\n          <a href=\"#sandbox\" class=\"btn btn-primary\">Launch Gateway</a>\n        </div>\n      </div>\n    </div>\n  </header>\n\n  <!-- Hero Section -->\n  <section class=\"hero-section\">\n    <div class=\"container\">\n      <div class=\"hero-grid\">\n        <div class=\"hero-content\">\n          <div class=\"hero-tag\">\n            <span class=\"hero-tag-dot\"></span>\n            <span>Universal AI Gateway & Protocol Translator</span>\n          </div>\n\n          <h1 class=\"hero-title\">\n            Run any coding agent on <span class=\"gradient\">any LLM model</span>.\n          </h1>\n\n          <p class=\"hero-subtitle\">\n            A high-performance local gateway bridging Claude Code, Codex CLI, Hermes Agent, OpenCode, and Pi to Google Gemini, OpenCode, Cloudflare Workers AI, and Ollama.\n          </p>\n\n          <div class=\"hero-cta-group\">\n            <div class=\"copy-install-box\">\n              <code>curl -fsSL https://pontis.khrees.com/install.sh | bash</code>\n              <button class=\"copy-btn\" onclick=\"copyInstallCmd(this)\">Copy</button>\n            </div>\n            <a href=\"#sandbox\" class=\"btn btn-primary\" style=\"padding: 10px 20px;\">Try Interactive Launcher</a>\n          </div>\n\n          <div class=\"hero-badges\">\n            <div class=\"hero-badge-item\"><span class=\"icon\">✓</span> 100% Free AI Studio & OpenCode Models</div>\n            <div class=\"hero-badge-item\"><span class=\"icon\">✓</span> Real-Time Bidirectional Translation</div>\n            <div class=\"hero-badge-item\"><span class=\"icon\">✓</span> AES-256-GCM Secure Vault</div>\n          </div>\n        </div>\n\n        <!-- Terminal Interactive Demonstration -->\n        <div class=\"terminal-card\">\n          <div class=\"terminal-header\">\n            <div class=\"window-controls\">\n              <span class=\"window-dot red\"></span>\n              <span class=\"window-dot yellow\"></span>\n              <span class=\"window-dot green\"></span>\n            </div>\n            <div class=\"terminal-tabs\">\n              <button class=\"t-tab active\" onclick=\"switchTerminalTab('claude', this)\">Claude Code</button>\n              <button class=\"t-tab\" onclick=\"switchTerminalTab('codex', this)\">Codex</button>\n              <button class=\"t-tab\" onclick=\"switchTerminalTab('hermes', this)\">Hermes</button>\n            </div>\n          </div>\n\n          <div class=\"terminal-body\" id=\"terminal-screen\">\n            <div class=\"t-line\"><span class=\"t-prompt\">$</span> <span class=\"t-cmd\">pontis claude</span></div>\n            <div class=\"t-line t-dim\">  ◆ Pontis Gateway v1.1.0</div>\n            <div class=\"t-line t-green\">  ✓ Proxy running on http://localhost:8787</div>\n            <div class=\"t-line t-green\">  ✓ Upstream verified: Google AI Studio (gemini-2.5-flash)</div>\n            <div class=\"t-line t-dim\">  ● Launching Claude Code...</div>\n            <div class=\"t-line\"><span class=\"t-cyan\">  · Spawning: claude</span></div>\n            <div class=\"t-line t-purple\">  Claude Code is ready. How can I help you today?</div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Section: Architecture & Protocol Translation Visualizer -->\n  <section class=\"section\" id=\"architecture\">\n    <div class=\"container\">\n      <div class=\"section-header\">\n        <span class=\"section-tag\">Architecture</span>\n        <h2 class=\"section-title\">Bidirectional Protocol Translation</h2>\n        <p class=\"section-desc\">\n          Pontis runs as an ultra-fast local proxy converting requests, parameters, tool calls, and streaming SSE tokens in real time.\n        </p>\n      </div>\n\n      <div class=\"bridge-diagram\">\n        <!-- Col 1: Agents -->\n        <div class=\"diagram-col\">\n          <div class=\"col-title\">1. Coding Agents</div>\n          <div class=\"diagram-card\"><span>Claude Code</span> <span class=\"badge-protocol\">/v1/messages</span></div>\n          <div class=\"diagram-card\"><span>Codex CLI</span> <span class=\"badge-protocol\">/v1/responses</span></div>\n          <div class=\"diagram-card\"><span>Hermes Agent</span> <span class=\"badge-protocol\">OpenAI Chat</span></div>\n          <div class=\"diagram-card\"><span>OpenCode</span> <span class=\"badge-protocol\">OpenAI API</span></div>\n          <div class=\"diagram-card\"><span>Pi Agent</span> <span class=\"badge-protocol\">Completions</span></div>\n        </div>\n\n        <div class=\"connector-arrow\">➔</div>\n\n        <!-- Col 2: Pontis Hub -->\n        <div class=\"hub-box\">\n          <div class=\"hub-title\">🌌 Pontis Gateway</div>\n          <div class=\"hub-desc\">Local Proxy on <code>http://localhost:8787</code></div>\n          <div class=\"hub-features\">\n            <div class=\"hub-feature-item\"><span class=\"chk\">✓</span> Protocol Engine (Anthropic ↔ OpenAI)</div>\n            <div class=\"hub-feature-item\"><span class=\"chk\">✓</span> Responses API Translation (Codex)</div>\n            <div class=\"hub-feature-item\"><span class=\"chk\">✓</span> SSE Stream Normalizer</div>\n            <div class=\"hub-feature-item\"><span class=\"chk\">✓</span> Encrypted Credential Vault</div>\n          </div>\n        </div>\n\n        <div class=\"connector-arrow\">➔</div>\n\n        <!-- Col 3: Upstream Providers -->\n        <div class=\"diagram-col\">\n          <div class=\"col-title\">3. Upstream LLMs</div>\n          <div class=\"diagram-card\"><span>Google AI Studio</span> <span class=\"badge-protocol\">Gemini 2.5</span></div>\n          <div class=\"diagram-card\"><span>OpenCode Cloud</span> <span class=\"badge-protocol\">Zen / Go Free</span></div>\n          <div class=\"diagram-card\"><span>Cloudflare AI</span> <span class=\"badge-protocol\">Workers AI</span></div>\n          <div class=\"diagram-card\"><span>Local Ollama / LM</span> <span class=\"badge-protocol\">Localhost</span></div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Section: Interactive Sandbox & Command Generator -->\n  <section class=\"section\" id=\"sandbox\">\n    <div class=\"container\">\n      <div class=\"section-header\">\n        <span class=\"section-tag\">Interactive Sandbox</span>\n        <h2 class=\"section-title\">Configure & Generate Launch Commands</h2>\n        <p class=\"section-desc\">\n          Select your target coding agent, provider, and model to generate ready-to-run terminal commands and environment configurations.\n        </p>\n      </div>\n\n      <div class=\"sandbox-panel\">\n        <div class=\"sandbox-sidebar\">\n          <div class=\"control-group\">\n            <label class=\"control-label\">1. Choose Coding Agent</label>\n            <div class=\"select-pill-group\">\n              <button class=\"pill-btn active\" onclick=\"setSandboxAgent('claude', this)\">Claude Code</button>\n              <button class=\"pill-btn\" onclick=\"setSandboxAgent('codex', this)\">Codex</button>\n              <button class=\"pill-btn\" onclick=\"setSandboxAgent('hermes', this)\">Hermes</button>\n              <button class=\"pill-btn\" onclick=\"setSandboxAgent('opencode', this)\">OpenCode</button>\n              <button class=\"pill-btn\" onclick=\"setSandboxAgent('pi', this)\">Pi Agent</button>\n            </div>\n          </div>\n\n          <div class=\"control-group\">\n            <label class=\"control-label\">2. Choose Provider</label>\n            <select class=\"custom-select\" id=\"sandbox-provider-select\" onchange=\"onSandboxProviderChange(this.value)\">\n              <option value=\"google\">Google AI Studio (Gemini 2.5)</option>\n              <option value=\"opencode\">OpenCode Cloud (Free Models)</option>\n              <option value=\"cloudflare\">Cloudflare Workers AI</option>\n              <option value=\"local\">Local Ollama / LM Studio</option>\n            </select>\n          </div>\n\n          <div class=\"control-group\">\n            <label class=\"control-label\">3. Select Model</label>\n            <select class=\"custom-select\" id=\"sandbox-model-select\" onchange=\"updateSandboxCode()\">\n              <option value=\"gemini-2.5-flash\">gemini-2.5-flash (Fast & Free)</option>\n              <option value=\"gemini-2.5-pro\">gemini-2.5-pro (Reasoning)</option>\n              <option value=\"gemma-2-27b-it\">gemma-2-27b-it</option>\n            </select>\n          </div>\n        </div>\n\n        <div class=\"sandbox-content\">\n          <div class=\"sandbox-code-block\">\n            <div class=\"code-title\">1-Click Pontis CLI Launcher</div>\n            <div class=\"code-body\" id=\"sandbox-cli-cmd\">pontis claude --provider google --model gemini-2.5-flash</div>\n          </div>\n\n          <div class=\"sandbox-code-block\">\n            <div class=\"code-title\">Or Set Standing Preferences</div>\n            <div class=\"code-body\" id=\"sandbox-config-cmd\">pontis config set provider google\npontis config set model gemini-2.5-flash\npontis claude</div>\n          </div>\n\n          <div class=\"sandbox-code-block\">\n            <div class=\"code-title\">Direct Agent Environment Variables (Optional Manual Wiring)</div>\n            <div class=\"code-body\" id=\"sandbox-env-cmd\">export ANTHROPIC_BASE_URL=\"http://localhost:8787\"</div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Section: Supported Providers -->\n  <section class=\"section\" id=\"providers\">\n    <div class=\"container\">\n      <div class=\"section-header\">\n        <span class=\"section-tag\">Supported Providers</span>\n        <h2 class=\"section-title\">Zero Friction AI Backends</h2>\n        <p class=\"section-desc\">\n          Authenticate once into Pontis's encrypted vault. Switch providers anytime with zero client reconfiguration.\n        </p>\n      </div>\n\n      <div class=\"grid-4\">\n        <!-- Google -->\n        <div class=\"provider-card\">\n          <div class=\"card-icon-header\">\n            <span style=\"font-size: 1.5rem;\">✨</span>\n            <span class=\"provider-badge badge-free\">Instant Free</span>\n          </div>\n          <h3 class=\"card-title\">Google AI Studio</h3>\n          <p class=\"card-desc\">\n            Use Gemini 2.5 Flash and Pro without a paid subscription using your free AI Studio API key.\n          </p>\n          <div class=\"model-pill-list\">\n            <span class=\"model-tag\">gemini-2.5-flash</span>\n            <span class=\"model-tag\">gemini-2.5-pro</span>\n            <span class=\"model-tag\">gemma-2-27b</span>\n          </div>\n        </div>\n\n        <!-- OpenCode -->\n        <div class=\"provider-card\">\n          <div class=\"card-icon-header\">\n            <span style=\"font-size: 1.5rem;\">⚡</span>\n            <span class=\"provider-badge badge-free\">Free Cloud</span>\n          </div>\n          <h3 class=\"card-title\">OpenCode Cloud</h3>\n          <p class=\"card-desc\">\n            Access free DeepSeek, Nemotron, Mimo, and Qwen models through OpenCode Zen endpoints.\n          </p>\n          <div class=\"model-pill-list\">\n            <span class=\"model-tag\">deepseek-v4-flash</span>\n            <span class=\"model-tag\">nemotron-3.5-lightning</span>\n            <span class=\"model-tag\">mimo-v2.5</span>\n          </div>\n        </div>\n\n        <!-- Cloudflare -->\n        <div class=\"provider-card\">\n          <div class=\"card-icon-header\">\n            <span style=\"font-size: 1.5rem;\">☁️</span>\n            <span class=\"provider-badge badge-cloud\">Global Edge</span>\n          </div>\n          <h3 class=\"card-title\">Cloudflare Workers AI</h3>\n          <p class=\"card-desc\">\n            Route through Cloudflare AI Gateway for edge caching, observability, and serverless LLMs.\n          </p>\n          <div class=\"model-pill-list\">\n            <span class=\"model-tag\">@cf/moonshot/kimi</span>\n            <span class=\"model-tag\">@cf/meta/llama-3.3</span>\n          </div>\n        </div>\n\n        <!-- Local -->\n        <div class=\"provider-card\">\n          <div class=\"card-icon-header\">\n            <span style=\"font-size: 1.5rem;\">💻</span>\n            <span class=\"provider-badge badge-local\">100% Offline</span>\n          </div>\n          <h3 class=\"card-title\">Local LLM Engines</h3>\n          <p class=\"card-desc\">\n            Connect directly to Ollama, LM Studio, or Llama.cpp running on your local workstation.\n          </p>\n          <div class=\"model-pill-list\">\n            <span class=\"model-tag\">llama3</span>\n            <span class=\"model-tag\">qwen2.5-coder</span>\n            <span class=\"model-tag\">mistral</span>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Section: CLI Manual & Commands -->\n  <section class=\"section\" id=\"cli\">\n    <div class=\"container\">\n      <div class=\"section-header\">\n        <span class=\"section-tag\">CLI Reference</span>\n        <h2 class=\"section-title\">Command-Line Interface</h2>\n        <p class=\"section-desc\">\n          Pontis provides a powerful terminal utility for credential management, agent installation, and interactive launches.\n        </p>\n      </div>\n\n      <div class=\"reference-table-wrap\">\n        <table class=\"ref-table\">\n          <thead>\n            <tr>\n              <th>Command</th>\n              <th>Description</th>\n              <th>Example</th>\n            </tr>\n          </thead>\n          <tbody>\n            <tr>\n              <td><code>pontis</code></td>\n              <td>Interactive wizard with 1-Click Fast Launch and keyboard navigation (<kbd>Tab</kbd>/<kbd>↑↓</kbd>)</td>\n              <td><code>pontis</code></td>\n            </tr>\n            <tr>\n              <td><code>pontis claude</code></td>\n              <td>Start proxy and launch Claude Code with auto-approved keys in <code>~/.claude.json</code></td>\n              <td><code>pontis claude</code></td>\n            </tr>\n            <tr>\n              <td><code>pontis codex</code></td>\n              <td>Start proxy and launch Codex CLI via Responses API translation</td>\n              <td><code>pontis codex</code></td>\n            </tr>\n            <tr>\n              <td><code>pontis hermes</code></td>\n              <td>Start proxy and launch Hermes Agent with OpenAI compatibility endpoints</td>\n              <td><code>pontis hermes</code></td>\n            </tr>\n            <tr>\n              <td><code>pontis opencode</code></td>\n              <td>Start proxy and launch OpenCode agent bridged to selected models</td>\n              <td><code>pontis opencode</code></td>\n            </tr>\n            <tr>\n              <td><code>pontis auth set &lt;provider&gt;</code></td>\n              <td>Save encrypted credentials into AES-256-GCM vault (<code>google</code>, <code>opencode</code>, <code>cloudflare</code>)</td>\n              <td><code>pontis auth set google</code></td>\n            </tr>\n            <tr>\n              <td><code>pontis models -p &lt;provider&gt;</code></td>\n              <td>List and interactively pick available models for any provider</td>\n              <td><code>pontis models -p google</code></td>\n            </tr>\n            <tr>\n              <td><code>pontis clients</code></td>\n              <td>View installed agent CLIs, versions, and install missing tools</td>\n              <td><code>pontis install claude</code></td>\n            </tr>\n          </tbody>\n        </table>\n      </div>\n    </div>\n  </section>\n\n  <!-- Section: FAQ -->\n  <section class=\"section\" id=\"faq\">\n    <div class=\"container\">\n      <div class=\"section-header\">\n        <span class=\"section-tag\">FAQ</span>\n        <h2 class=\"section-title\">Frequently Asked Questions</h2>\n      </div>\n\n      <div class=\"faq-list\">\n        <div class=\"faq-item\">\n          <button class=\"faq-trigger\" onclick=\"toggleFaq(this)\">\n            <span>How does Pontis translate Anthropic and OpenAI protocols?</span>\n            <span class=\"faq-icon\">+</span>\n          </button>\n          <div class=\"faq-content\">\n            Pontis translates Anthropic Messages format (<code>/v1/messages</code>) into OpenAI Chat Completions (<code>/v1/chat/completions</code>), OpenAI Responses API (<code>/v1/responses</code>) for Codex, and SSE event streams on the fly. Tool calls, thinking tags, and streaming tokens are preserved bidirectionally.\n          </div>\n        </div>\n\n        <div class=\"faq-item\">\n          <button class=\"faq-trigger\" onclick=\"toggleFaq(this)\">\n            <span>Are Google Gemini and OpenCode models really free?</span>\n            <span class=\"faq-icon\">+</span>\n          </button>\n          <div class=\"faq-content\">\n            Yes! Google AI Studio provides free API keys with generous rate limits for <code>gemini-2.5-flash</code>, <code>gemini-2.5-pro</code>, and <code>gemma</code> models. OpenCode provides free cloud models including <code>deepseek-v4-flash-free</code>, <code>nemotron-3.5-lightning-free</code>, and <code>mimo-v2.5-free</code>.\n          </div>\n        </div>\n\n        <div class=\"faq-item\">\n          <button class=\"faq-trigger\" onclick=\"toggleFaq(this)\">\n            <span>Where are my API credentials stored?</span>\n            <span class=\"faq-icon\">+</span>\n          </button>\n          <div class=\"faq-content\">\n            Credentials are encrypted using AES-256-GCM and stored in <code>~/.pontis/credentials.enc</code> with file permission <code>0o600</code>. Decryption keys are isolated in <code>~/.pontis/.secret</code> and never logged or exposed.\n          </div>\n        </div>\n\n        <div class=\"faq-item\">\n          <button class=\"faq-trigger\" onclick=\"toggleFaq(this)\">\n            <span>Can I use Pontis completely offline?</span>\n            <span class=\"faq-icon\">+</span>\n          </button>\n          <div class=\"faq-content\">\n            Yes! Set your provider to <code>local</code> (<code>pontis config set provider local</code>) pointing to your local Ollama (<code>http://localhost:11434/v1</code>) or LM Studio server. Pontis works with 100% offline local inference.\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- Footer -->\n  <footer class=\"site-footer\">\n    <div class=\"container\">\n      <div class=\"footer-inner\">\n        <div>\n          <strong>Pontis AI Gateway</strong> — Universal CLI Runtime Bridge. MIT Licensed.\n        </div>\n        <div style=\"display: flex; gap: 20px;\">\n          <a href=\"#architecture\">Architecture</a>\n          <a href=\"#sandbox\">Sandbox</a>\n          <a href=\"#cli\">CLI Manual</a>\n          <a href=\"https://github.com/khrees/pontis\" target=\"_blank\" rel=\"noreferrer\">GitHub</a>\n        </div>\n      </div>\n    </div>\n  </footer>\n\n  <!-- Interactive JavaScript Logic -->\n  <script>\n    // 1. Copy Install Command\n    function copyInstallCmd(btn) {\n      navigator.clipboard.writeText(\"curl -fsSL https://pontis.khrees.com/install.sh | bash\");\n      const original = btn.textContent;\n      btn.textContent = \"Copied!\";\n      btn.style.color = \"#34d399\";\n      setTimeout(() => {\n        btn.textContent = original;\n        btn.style.color = \"\";\n      }, 2000);\n    }\n\n    // 2. Terminal Tab Switcher\n    const terminalDemos = {\n      claude: [\n        '<div class=\"t-line\"><span class=\"t-prompt\">$</span> <span class=\"t-cmd\">pontis claude</span></div>',\n        '<div class=\"t-line t-dim\">  ◆ Pontis Gateway v1.1.0</div>',\n        '<div class=\"t-line t-green\">  ✓ Auto-approved key in ~/.claude.json</div>',\n        '<div class=\"t-line t-green\">  ✓ Translating /v1/messages → Google Gemini (gemini-2.5-flash)</div>',\n        '<div class=\"t-line\"><span class=\"t-cyan\">  · Spawning: claude</span></div>',\n        '<div class=\"t-line t-purple\">  Claude Code is ready. How can I help you today?</div>'\n      ],\n      codex: [\n        '<div class=\"t-line\"><span class=\"t-prompt\">$</span> <span class=\"t-cmd\">pontis codex</span></div>',\n        '<div class=\"t-line t-dim\">  ◆ Pontis Gateway v1.1.0</div>',\n        '<div class=\"t-line t-green\">  ✓ Responses API bridge active on /v1/responses</div>',\n        '<div class=\"t-line\"><span class=\"t-cyan\">  · Spawning: codex --profile pontis</span></div>',\n        '<div class=\"t-line t-purple\">  Codex CLI connected to Pontis. Streaming responses...</div>'\n      ],\n      hermes: [\n        '<div class=\"t-line\"><span class=\"t-prompt\">$</span> <span class=\"t-cmd\">pontis hermes</span></div>',\n        '<div class=\"t-line t-dim\">  ◆ Pontis Gateway v1.1.0</div>',\n        '<div class=\"t-line t-green\">  ✓ Configured HERMES_API_BASE=http://localhost:8787/v1</div>',\n        '<div class=\"t-line\"><span class=\"t-cyan\">  · Spawning: hermes --model gemini-2.5-flash</span></div>',\n        '<div class=\"t-line t-purple\">  Hermes Agent v0.4 initialized. Ready.</div>'\n      ]\n    };\n\n    function switchTerminalTab(client, btn) {\n      document.querySelectorAll('.terminal-tabs .t-tab').forEach(t => t.classList.remove('active'));\n      btn.classList.add('active');\n      const screen = document.getElementById('terminal-screen');\n      screen.innerHTML = (terminalDemos[client] || terminalDemos.claude).join('');\n    }\n\n    // 3. Sandbox Interactive Generator\n    let currentAgent = 'claude';\n    let currentProvider = 'google';\n\n    const providerModels = {\n      google: [\n        { id: 'gemini-2.5-flash', label: 'gemini-2.5-flash (Fast & Free)' },\n        { id: 'gemini-2.5-pro', label: 'gemini-2.5-pro (Reasoning)' },\n        { id: 'gemma-2-27b-it', label: 'gemma-2-27b-it' }\n      ],\n      opencode: [\n        { id: 'deepseek-v4-flash-free', label: 'deepseek-v4-flash-free' },\n        { id: 'nemotron-3.5-lightning-free', label: 'nemotron-3.5-lightning-free' },\n        { id: 'mimo-v2.5-free', label: 'mimo-v2.5-free' },\n        { id: 'qwen3.6-plus', label: 'qwen3.6-plus' }\n      ],\n      cloudflare: [\n        { id: '@cf/moonshotai/kimi-k2.6', label: '@cf/moonshotai/kimi-k2.6' },\n        { id: '@cf/meta/llama-3.3-70b-instruct', label: '@cf/meta/llama-3.3-70b-instruct' }\n      ],\n      local: [\n        { id: 'llama3', label: 'llama3 (Ollama / Local)' },\n        { id: 'qwen2.5-coder', label: 'qwen2.5-coder' },\n        { id: 'mistral', label: 'mistral' }\n      ]\n    };\n\n    function setSandboxAgent(agent, btn) {\n      document.querySelectorAll('.select-pill-group .pill-btn').forEach(b => b.classList.remove('active'));\n      btn.classList.add('active');\n      currentAgent = agent;\n      updateSandboxCode();\n    }\n\n    function onSandboxProviderChange(provider) {\n      currentProvider = provider;\n      const modelSelect = document.getElementById('sandbox-model-select');\n      const models = providerModels[provider] || providerModels.google;\n      modelSelect.innerHTML = models.map(m => `<option value=\"${m.id}\">${m.label}</option>`).join('');\n      updateSandboxCode();\n    }\n\n    function updateSandboxCode() {\n      const model = document.getElementById('sandbox-model-select').value;\n      const cliCmd = `pontis ${currentAgent} --provider ${currentProvider} --model ${model}`;\n      const configCmd = `pontis config set provider ${currentProvider}\\npontis config set model ${model}\\npontis ${currentAgent}`;\n      \n      let envCmd = `export OPENAI_BASE_URL=\"http://localhost:8787/v1\"`;\n      if (currentAgent === 'claude') {\n        envCmd = `export ANTHROPIC_BASE_URL=\"http://localhost:8787\"`;\n      } else if (currentAgent === 'hermes') {\n        envCmd = `export HERMES_API_BASE=\"http://localhost:8787/v1\"\\nexport HERMES_MODEL=\"${model}\"`;\n      }\n\n      document.getElementById('sandbox-cli-cmd').textContent = cliCmd;\n      document.getElementById('sandbox-config-cmd').textContent = configCmd;\n      document.getElementById('sandbox-env-cmd').textContent = envCmd;\n    }\n\n    // 4. FAQ Accordion Toggle\n    function toggleFaq(btn) {\n      const item = btn.parentElement;\n      item.classList.toggle('open');\n    }\n  </script>\n</body>\n</html>\n";
